package fpv.render;
/** Opaque native-textured bed + separate alpha surface. Bubbles/ice are cosmetic shader geometry/materials. */
final class LiquidSurfaceShaders {
 static final String WAVE="float wave(vec2 p,float t){return 0.12*(0.75+0.25*sin(p.x*0.11+p.y*0.09))*(0.65*sin(p.x*0.73+p.y*0.41+t*0.9)+0.35*sin(p.x*(-0.37)+p.y*0.83-t*0.63));}";
 static final String HASH="float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}";
 static final String VERTEX="attribute vec3 a_position;attribute vec4 a_color;attribute vec2 a_texCoord0;uniform mat4 u_combined;uniform vec3 u_camera;uniform float u_time;uniform float u_waves;varying vec4 v_color;varying vec2 v_uv;varying vec3 v_pos;varying float v_kind;"+WAVE+HASH+
 "void main(){v_pos=a_position;v_color=a_color;v_uv=a_texCoord0;v_kind=floor((a_color.a-10.0)/2.0);float weight=clamp(a_color.a-10.0-v_kind*2.0,0.0,1.0);if(u_waves>0.5){v_pos.y+=weight*wave(v_pos.xz,u_time);if(v_kind>1.5&&v_kind<3.5){vec2 cell=floor(v_pos.xz/3.0);vec2 centre=(cell+vec2(0.2+0.6*hash(cell),0.2+0.6*hash(cell+7.0)))*3.0;float phase=fract(u_time*(0.13+0.07*hash(cell+3.0))+hash(cell+2.0));float r=0.6+0.55*hash(cell+5.0);float dome=sqrt(max(0.0,1.0-dot(v_pos.xz-centre,v_pos.xz-centre)/(r*r)));if(phase<0.83)v_pos.y+=weight*0.90*dome*sin(phase/0.83*3.14159);}}gl_Position=u_combined*vec4(v_pos,1.0);}";
 static final String FRAGMENT="uniform sampler2D u_texture;uniform vec3 u_camera;uniform float u_time;uniform float u_waves;uniform float u_ambient;varying vec4 v_color;varying vec2 v_uv;varying vec3 v_pos;varying float v_kind;"+HASH+
 "void main(){vec4 native=texture2D(u_texture,v_uv);vec3 c=mix(native.rgb,v_color.rgb,0.82);float a=0.38;vec2 p=v_pos.xz;vec2 cell=floor(p/3.0);float rnd=hash(cell);float phase=fract(u_time*(0.13+0.07*hash(cell+3.0))+hash(cell+2.0));vec2 centre=(cell+vec2(0.2+0.6*rnd,0.2+0.6*hash(cell+7.0)))*3.0;float radius=0.6+0.55*hash(cell+5.0);float d=length(p-centre)/radius;"+
 "if(v_kind<1.5){a=0.34;if(u_waves>0.5){float dx=0.07*cos(p.x*0.73+p.y*0.41+u_time*0.9);float dz=0.07*cos(p.x*(-0.37)+p.y*0.83-u_time*0.63);vec3 n=normalize(vec3(-dx,1.0,-dz));vec3 view=normalize(u_camera-v_pos);float sun=pow(max(0.0,dot(reflect(-normalize(vec3(0.35,0.85,-0.3)),n),view)),48.0);float glitter=pow(max(0.0,sin(p.x*13.0+p.y*9.0+u_time*1.8)),12.0);c+=vec3(0.9,0.95,1.0)*(sun*0.9+glitter*0.15);a+=0.15*pow(1.0-abs(dot(n,view)),3.0);}}"+
 "else if(v_kind<3.5){a=v_kind>2.5?0.90:0.72;if(u_waves>0.5){float ring=(1.0-smoothstep(0.03,0.13,abs(d-mix(0.15,1.35,phase))))*(1.0-phase);float cap=(1.0-smoothstep(0.25,0.95,d))*sin(min(1.0,phase/0.83)*3.14159);if(v_kind>2.5)c=mix(c,vec3(1.0,0.76,0.18),clamp(cap*0.65+ring*0.8,0.0,0.9));else c+=vec3(0.24,0.27,0.19)*(cap+ring);}}"+
 "else if(v_kind<4.5){a=0.40;if(u_waves>0.5){vec2 q=p-centre;float gather=0.5+0.5*sin(u_time*0.45+rnd*6.28);q+=vec2(sin(u_time*0.25+rnd*8.0),cos(u_time*0.3+rnd*8.0))*(1.0-gather)*0.5;float diamond=abs(q.x*0.8+q.y*0.3)+abs(q.y*0.8-q.x*0.3);float size=(0.20+0.75*rnd)*sin(phase*3.14159);float ice=1.0-smoothstep(size,size+0.07,diamond);c=mix(c,vec3(0.7,0.94,1.0),ice*0.85);a=mix(a,0.84,ice);}}else a=0.65;gl_FragColor=vec4(c*u_ambient,a*native.a);}";
}
